#pragma once

#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

// Registry of kernel imports. Every import the game references gets a weak stub (generated by
// lr::pipeline::render_import_stubs) that calls unimplemented_import(); a real implementation is a strong
// definition made with LR_KERNEL_EXPORT, which also records the name for `--coverage`.
//
// This header deliberately does not include ppc_context.h (it needs the generated ppc_config.h first);
// translation units that use LR_KERNEL_EXPORT include ppc_config.h + ppc_context.h themselves.

namespace lr::kernel {

// Thrown by an unimplemented import stub; caught by run_guest. The only exception that crosses runtime internals.
struct UnimplementedImport {
  std::string name;
  uint32_t caller;                 // guest LR at the call
  std::vector<std::string> trail;  // last traced imports, oldest first
};

// Throws UnimplementedImport carrying the calling thread's current trail.
[[noreturn]] void unimplemented_import(const char* name, uint32_t caller_lr);

// Records an implemented import call in a per-thread ring buffer (last 32).
void trace(const char* name);

void register_implemented(const char* name);
bool is_implemented(std::string_view name);

// "Unimplemented import: <name>\nCalled from: 0x<caller>\nTrail (last N): a -> b\n"
std::string format_report(const UnimplementedImport& e);

}  // namespace lr::kernel

// Defines the strong implementation of import `Name` and registers it. Usage:
//   LR_KERNEL_EXPORT(XamInputGetState) { lr::kernel::trace("XamInputGetState"); ctx.r3.u32 = 0; }
// Use it at global scope so it overrides the weak stub of the same symbol.
// The body sees `ctx` and `base`; add `(void)base;` if unused (-Werror).
#define LR_KERNEL_EXPORT(Name)                                                                          \
  [[maybe_unused]] static const bool lr_kernel_registered_##Name = (::lr::kernel::register_implemented(#Name), true); \
  PPC_FUNC(__imp__##Name)
